import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import math
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

cpp_source = """
torch::Tensor moe_gated_gemm_forward(
    torch::Tensor x,
    torch::Tensor gate_proj,
    torch::Tensor up_proj,
    torch::Tensor down_proj,
    torch::Tensor expert_indices,
    torch::Tensor expert_weights);
"""

hip_source = """
#include <hip/hip_runtime.h>
#include <c10/cuda/CUDAGuard.h>

#define CEILDIV(a, b) ((a + b - 1) / b)

#define SILU(x) ((x) / (1.0f + expf(-(x))))

__global__ void moe_gated_gemm_kernel(
    const float* __restrict__ x,
    const float* __restrict__ gate_proj,
    const float* __restrict__ up_proj,
    const float* __restrict__ down_proj,
    const int* __restrict__ expert_indices,
    const float* __restrict__ expert_weights,
    float* __restrict__ output,
    const int num_tokens,
    const int num_experts,
    const int hidden_size,
    const int intermediate_size,
    const int top_k
) {

    const int tid = blockIdx.x * blockDim.x + threadIdx.x;

    if (tid >= num_tokens * top_k * hidden_size) {
        return;
    }

    const int token_idx = (tid / hidden_size) / top_k;
    const int expert_slot = (tid / hidden_size) % top_k;
    const int hidden_dim = tid % hidden_size;

    if (token_idx >= num_tokens) {
        return;
    }

    const int expert_id = expert_indices[token_idx * top_k + expert_slot];
    const float expert_weight = expert_weights[token_idx * top_k + expert_slot];

    if (expert_id < 0 || expert_id >= num_experts) {
        return;
    }

    __shared__ float shared_x[64];
    const int warp_id = threadIdx.x / 32;
    const int lane_id = threadIdx.x % 32;
    const int tokens_per_block = blockDim.x / hidden_size;

    const int local_token = threadIdx.x / hidden_size;
    const int local_hidden = threadIdx.x % hidden_size;

    if (local_token < tokens_per_block && token_idx + local_token < num_tokens) {
        shared_x[local_token * hidden_size + local_hidden] = x[(token_idx) * hidden_size + local_hidden];
    }
    __syncthreads();

    const float* expert_gate_proj = gate_proj + expert_id * intermediate_size * hidden_size;
    const float* expert_up_proj = up_proj + expert_id * intermediate_size * hidden_size;
    const float* expert_down_proj = down_proj + expert_id * hidden_size * intermediate_size;

    if (threadIdx.x < intermediate_size) {
        float gate_val = 0.0f;
        float up_val = 0.0f;


        #pragma unroll
        for (int i = 0; i < hidden_size; i += 4) {
            float x_val1 = shared_x[i];
            float x_val2 = shared_x[i + 1];
            float x_val3 = shared_x[i + 2];
            float x_val4 = shared_x[i + 3];

            gate_val += expert_gate_proj[threadIdx.x * hidden_size + i] * x_val1;
            gate_val += expert_gate_proj[threadIdx.x * hidden_size + i + 1] * x_val2;
            gate_val += expert_gate_proj[threadIdx.x * hidden_size + i + 2] * x_val3;
            gate_val += expert_gate_proj[threadIdx.x * hidden_size + i + 3] * x_val4;

            up_val += expert_up_proj[threadIdx.x * hidden_size + i] * x_val1;
            up_val += expert_up_proj[threadIdx.x * hidden_size + i + 1] * x_val2;
            up_val += expert_up_proj[threadIdx.x * hidden_size + i + 2] * x_val3;
            up_val += expert_up_proj[threadIdx.x * hidden_size + i + 3] * x_val4;
        }

        gate_val = SILU(gate_val);
        float intermediate_val = gate_val * up_val;


        float down_val = 0.0f;
        #pragma unroll
        for (int i = 0; i < intermediate_size; i += 8) {
            down_val += expert_down_proj[hidden_dim * intermediate_size + i + 0] * intermediate_val;
        }


        atomicAdd(&output[token_idx * hidden_size + hidden_dim], down_val * expert_weight);
    }
}
torch::Tensor moe_gated_gemm_forward(
    torch::Tensor x,
    torch::Tensor gate_proj,
    torch::Tensor up_proj,
    torch::Tensor down_proj,
    torch::Tensor expert_indices,
    torch::Tensor expert_weights
) {
    const at::cuda::OptionalCUDAGuard guard(device_of(x));

    const int num_tokens = x.size(0);
    const int hidden_size = x.size(1);
    const int num_experts = gate_proj.size(0);
    const int intermediate_size = gate_proj.size(1);
    const int top_k = expert_indices.size(1);

    auto output = torch::zeros({num_tokens, hidden_size}, torch::dtype(torch::kFloat32).device(x.device()));

    if (num_tokens == 0) {
        return output;
    }

    const int threads_per_block = 128;
    const int total_elements = num_tokens * top_k * hidden_size;
    const int num_blocks = CEILDIV(total_elements, threads_per_block);

    hipLaunchKernelGGL(
        moe_gated_gemm_kernel,
        dim3(num_blocks),
        dim3(threads_per_block),
        0, 0,
        x.data_ptr<float>(),
        gate_proj.data_ptr<float>(),
        up_proj.data_ptr<float>(),
        down_proj.data_ptr<float>(),
        expert_indices.data_ptr<int>(),
        expert_weights.data_ptr<float>(),
        output.data_ptr<float>(),
        num_tokens,
        num_experts,
        hidden_size,
        intermediate_size,
        top_k
    );

    return output;
}
"""

# Load the custom kernel
moe_gemm = load_inline(
    name="moe_gated_gemm",
    cpp_sources=cpp_source,
    functions=["moe_gated_gemm_forward"],
    verbose=True,
    is_python_module=True,
    with_cuda=True,
)

class ModelNew(nn.Module):
    def __init__(
        self,
        hidden_size: int,
        intermediate_size: int,
        num_experts: int,
    ):
        super().__init__()
        self.hidden_size = hidden_size
        self.intermediate_size = intermediate_size
        self.num_experts = num_experts

        self.gate_proj = nn.Parameter(
            torch.randn(num_experts, intermediate_size, hidden_size) * 0.02
        )
        self.up_proj = nn.Parameter(
            torch.randn(num_experts, intermediate_size, hidden_size) * 0.02
        )
        self.down_proj = nn.Parameter(
            torch.randn(num_experts, hidden_size, intermediate_size) * 0.02
        )

        self.moe_gemm_kernel = moe_gemm

    def forward(
        self,
        x: torch.Tensor,
        expert_indices: torch.Tensor,
        expert_weights: torch.Tensor,
    ) -> torch.Tensor:
        batch, seq_len, _ = x.shape

        x_flat = x.view(batch * seq_len, self.hidden_size)

        # Reshape indices and weights for kernel
        expert_indices_flat = expert_indices.view(batch * seq_len, -1)
        expert_weights_flat = expert_weights.view(batch * seq_len, -1)

        # Call fused kernel
        output_flat = self.moe_gemm_kernel.moe_gated_gemm_forward(
            x_flat,
            self.gate_proj,
            self.up_proj,
            self.down_proj,
            expert_indices_flat.int(),
            expert_weights_flat.float()
        )

        return output_flat.view(batch, seq_len, self.hidden_size)

# Configuration
batch_size = 4
seq_len = 2048
hidden_size = 4096
intermediate_size = 14336
num_experts = 8
top_k = 2

def get_inputs():
    x = torch.randn(batch_size, seq_len, hidden_size)

    expert_indices = torch.stack([
        torch.randperm(num_experts)[:top_k]
        for _ in range(batch_size * seq_len)
    ]).view(batch_size, seq_len, top_k)

    expert_weights = F.softmax(torch.randn(batch_size, seq_len, top_k), dim=-1)

    return [x, expert_indices, expert_weights]

def get_init_inputs():
    return [hidden_size, intermediate_size, num_experts]

