hip_source = """
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <c10/cuda/CUDAGuard.h>

#define CEILDIV(a, b) ((a + b - 1) / b)

#define SILU(x) ((x) / (1.0f + expf(-(x))))

__global__ void moe_gated_gemm_kernel(
    const float* __restrict__ x,
    const float* __restrict__ gate_proj,
    const float* __restrict__ up_proj,
    const float* __restrict__ down_proj,
    const int* __restrict__ expert_indices,
    const float* __restrict__ expert_weights,
    float* __restrict__ output,
    const int num_tokens,
    const int num_experts,
    const int hidden_size,
    const int intermediate_size,
    const int top_k
) {
    const int tid = blockIdx.x * blockDim.x + threadIdx.x;
    const int warp_size = 32;

    if (tid >= num_tokens * top_k * hidden_size) {
        return;
    }

    const int token_idx = tid / (top_k * hidden_size);
    const int expert_slot = (tid / hidden_size) % top_k;
    const int hidden_dim = tid % hidden_size;

    if (token_idx >= num_tokens) {
        return;
    }

    const int expert_id = expert_indices[token_idx * top_k + expert_slot];
    const float expert_weight = expert_weights[token_idx * top_k + expert_slot];

    if (expert_id < 0 || expert_id >= num_experts) {
        return;
    }

    __shared__ float shared_x[64];

    const int tokens_per_warp = warp_size / hidden_size;
    const int local_token_idx = (threadIdx.x / hidden_size);
    const int local_hidden_idx = (threadIdx.x % hidden_size);

    if (local_token_idx < tokens_per_warp && token_idx * tokens_per_warp + local_token_idx < num_tokens) {
        shared_x[local_hidden_idx] = x[(token_idx * tokens_per_warp + local_token_idx) * hidden_size + local_hidden_idx];
    }
    __syncthreads();

    const float* expert_gate_proj = gate_proj + expert_id * intermediate_size * hidden_size;
    const float* expert_up_proj = up_proj + expert_id * intermediate_size * hidden_size;
    const float* expert_down_proj = down_proj + expert_id * hidden_size * intermediate_size;

    __shared__ float gate_result[64];
    __shared__ float up_result[64];
    __shared__ float intermediate_result[64];

    const int lane_id = threadIdx.x % warp_size;
    const int work_per_thread = intermediate_size / warp_size;

    if (work_per_thread > 0 && lane_id < warp_size) {
        float gate_acc = 0.0f;
        float up_acc = 0.0f;

        const int start_idx = lane_id * work_per_thread;
        const int end_idx = start_idx + work_per_thread;

        #pragma unroll 4
        for (int i = start_idx; i < end_idx; i++) {
            float gate_dot = 0.0f;
            float up_dot = 0.0f;

            #pragma unroll 8
            for (int j = 0; j < hidden_size; j++) {
                float x_val = x[token_idx * hidden_size + j];
                gate_dot += expert_gate_proj[i * hidden_size + j] * x_val;
                up_dot += expert_up_proj[i * hidden_size + j] * x_val;
            }

            gate_acc += gate_dot;
            up_acc += up_dot;
        }

        // Compute SiLU and multiply
        float silu_gate = SILU(gate_acc);
        intermediate_result[threadIdx.x] = silu_gate * up_acc;
    }
    __syncthreads();

    // Now do the down projection (intermediate -> hidden)
    if (lane_id < intermediate_size) {
        float down_acc = 0.0f;

        #pragma unroll 4
        for (int i = 0; i < intermediate_size; i++) {
            down_acc += expert_down_proj[hidden_dim * intermediate_size + i] * intermediate_result[i];
        }

        // Accumulate weighted result
        atomicAdd(&output[token_idx * hidden_size + hidden_dim], down_acc * expert_weight);
    }
}

torch::Tensor moe_gated_gemm_forward(
    torch::Tensor x,
    torch::Tensor gate_proj,
    torch::Tensor up_proj,
    torch::Tensor down_proj,
    torch::Tensor expert_indices,
    torch::Tensor expert_weights
) {
    auto device = x.device();
    at::cuda::OptionalCUDAGuard device_guard(device);

    const int num_tokens = x.size(0);
    const int hidden_size = x.size(1);
    const int num_experts = gate_proj.size(0);
    const int intermediate_size = gate_proj.size(1);
    const int top_k = expert_indices.size(1);

    auto output = torch::zeros({num_tokens, hidden_size}, torch::dtype(torch::kFloat32).device(device));

    if (num_tokens == 0 || top_k == 0) {
        return output;
    }

    const int threads_per_block = 256;
    const int total_elements = num_tokens * top_k * hidden_size;
    const int num_blocks = CEILDIV(total_elements, threads_per_block);

    hipLaunchKernelGGL(
        moe_gated_gemm_kernel,
        dim3(num_blocks),
        dim3(threads_per_block),
        0, 0,
        x.data_ptr<float>(),
        gate_proj.data_ptr<float>(),
        up_proj.data_ptr<float>(),
        down_proj.data_ptr<float>(),
        expert_indices.data_ptr<int>(),
        expert_weights.data_ptr<float>(),
        output.data_ptr<float>(),
        num_tokens,
        num_experts,
        hidden_size,
        intermediate_size,
        top_k
    );

    return output;
}
"""

moe_gemm = load_inline(
