    const int hidden_size,
    const int intermediate_size,
    const int top_k
) {
    const int token_idx = blockIdx.x;
    if (token_idx >= num_tokens) return;

    const int hidden_dim = threadIdx.x;
    if (hidden_dim >= hidden_size) return;

    for (int expert_slot = 0; expert_slot < top_k; expert_slot++) {
        const int expert_id = expert_indices[token_idx * top_k + expert_slot];
        const float expert_weight = expert_weights[token_idx * top_k + expert_slot];

        if (expert_id < 0 || expert_id >= gridDim.y) continue;

        const float* expert_gate = gate_proj + expert_id * intermediate_size * hidden_size;
        const float* expert_up = up_proj + expert_id * intermediate_size * hidden_size;
        const float* expert_down = down_proj + expert_id * hidden_size * intermediate_size;

        // Load token input
        const float* token_x = x + token_idx * hidden_size;

        // Compute intermediate projection using shared memory for caching
        __shared__ float inter_cache[128];

        float inter_sum = 0.0f;

        for (int i = threadIdx.x; i < intermediate_size; i += blockDim.x) {
            float gate_val = 0.0f;
